WITH parsed AS (SELECT id, log_ts, level, latency_ms, status_code, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, COALESCE(context['region'], 'none') AS region_or_default, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region FROM app_logs WHERE log_ts >= '2024-06-23') SELECT *, CORR(status_code, latency_ms) OVER w_running AS corr_status_code_latency_ms, LEAD(status_code, 1) OVER w_grp AS next_status_code, LEAD(latency_ms, 1) OVER w_grp AS next_latency_ms FROM parsed WINDOW w_running AS (PARTITION BY level), w_grp AS (PARTITION BY level ORDER BY latency_ms, id);
